\begin{document}
\section{Theory}
The expected prediction error at a query point decomposes into three
interpretable terms, summarised in Equation~\eqref{eq:total} below.
\begin{align}
\mathbb{E}\!\left[(y_0 - \hat{f}(x_0))^2\right] &= \sigma_\varepsilon^2 + \left(f(x_0) - \mathbb{E}\hat{f}(x_0)\right)^2 + \mathbb{E}\!\left[\left(\hat{f}(x_0) - \mathbb{E}\hat{f}(x_0)\right)^2\right] . \label{eq:total}\\
\sigma_\varepsilon^2 &= \mathrm{Var}(y_0 \mid x_0) , \label{eq:noise}\\
\left(f(x_0) - \mathbb{E}\hat{f}(x_0)\right)^2 &= \left(\mathbb{E}\hat{f}(x_0) - f(x_0)\right)^2 , \label{eq:bias2}
\end{align}
The three terms are the total error, the irreducible noise, and the
squared bias, and Equation~\eqref{eq:noise} sets the floor that no
learner can beat.
\end{document}
